+        return centroid;
+    }
+
+    // maintain bwc by making bounding box available to ScriptDocValues.GeoPoints
+    @Override
+    public BoundingBox<T> getInternalBoundingBox() {
+        return boundingBox;
+    }
+
+    @Override
+    public T getInternalLabelPosition() {
+        return values[labelIndex];
+    }
+
+    @Override
+    public String getName() {
+        return name;
+    }
+
+    @Override
+    public boolean isEmpty() {
+        return count == 0;
+    }
+
+    @Override
+    public int size() {
+        return count;
+    }
+
+    public T get(T defaultValue) {
+        return get(0, defaultValue);
+    }
+
+    public T get(int index, T defaultValue) {
+        if (isEmpty() || index < 0 || index >= count) {
+            return defaultValue;
+        }
+
+        return values[index];
+    }
+
+    @Override
+    public Iterator<T> iterator() {
+        return new Iterator<>() {
+            private int index = 0;
+
+            @Override
+            public boolean hasNext() {
+                return index < count;
+            }
+
+            @Override
+            public T next() {
+                if (hasNext() == false) {
+                    throw new NoSuchElementException();
+                }
